export function t(lang: Lang, key: string): string {
  const row = phrases[key];
  if (!row) throw new Error(`Missing translation: ${key}`);
  return row[index[lang]];
}
export function productText(lang: Lang, slug: string, field: 'name'|'note'): string {
  const id: Record<string,string> = {'peppermint-oil':'peppermint','cornmint-oil':'cornmint','spearmint-oil':'spearmint','dementholised-oil':'dementholised','menthol-crystals':'menthol'};
  return t(lang,`product.${id[slug]}.${field}`);
}
export function familyText(lang: Lang, family: string): string {return t(lang,family==='Natural oils'?'family.natural':'family.rectified');}
export function sourceText(lang: Lang, latin: string): string {return latin==='Mint-derived oil'?t(lang,'product.mintDerivedOil'):latin==='Mint-derived menthol'?t(lang,'product.mintDerivedMenthol'):latin;}
export function useText(lang: Lang, value: string): string {
  const map: Record<string,string>={'Flavours & fragrances':'use.flavours','Confectionery':'use.confectionery','Oral care':'use.oral','Pharmaceuticals':'use.pharma'};
  return map[value]?t(lang,map[value]):value;
}

export function segmentText(lang:Lang,slug:string,field:'name'|'line'|'body'|'need'):string {
  const ids:Record<string,string>={'flavours-fragrances':'flavours','confectionery':'confectionery','pharmaceuticals':'pharma','oral-care':'oral','distributors':'distributors'};
  return t(lang,`segment.${ids[slug]}.${field}`);
}
